CREATE OR REPLACE FUNCTION public.gerar_checape(p_mes uuid)
 RETURNS integer
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
DECLARE
  total integer;
  tendencias integer;
BEGIN
  total := private.gerar_checape(p_mes);
  tendencias := private.gerar_alertas_tendencia(p_mes);
  RETURN total + tendencias;
END;
$function$
